using System;
using Xunit;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        // Person is abstract, use Student as concrete implementation
        [Fact]
        public void FullName_WithLastAndFirstName_ReturnsLastCommaFirst()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "John"
            };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal("Smith, John", fullName);
        }

        [Fact]
        public void FullName_WithEmptyNames_ReturnsComma()
        {
            // Arrange
            var student = new Student
            {
                LastName = "",
                FirstMidName = ""
            };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal(", ", fullName);
        }

        [Theory]
        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
        [InlineData("Van Der Berg", "Jan", "Van Der Berg, Jan")]
        [InlineData("Doe", "Jane", "Doe, Jane")]
        public void FullName_VariousNames_ReturnsExpectedFormat(string lastName, string firstName, string expected)
        {
            // Arrange
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstName
            };

            // Act & Assert
            Assert.Equal(expected, student.FullName);
        }

        [Fact]
        public void ID_SetAndGet_ReturnsCorrectValue()
        {
            // Arrange
            var student = new Student { ID = 42 };

            // Assert
            Assert.Equal(42, student.ID);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void Student_DefaultEnrollments_IsNull()
        {
            // Arrange & Act
            var student = new Student();

            // Assert
            Assert.Null(student.Enrollments);
        }

        [Fact]
        public void Student_SetEnrollmentDate_ReturnsCorrectDate()
        {
            // Arrange
            var date = new DateTime(2024, 9, 1);
            var student = new Student { EnrollmentDate = date };

            // Assert
            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Student_InheritsFromPerson_HasFullName()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = DateTime.Now
            };

            // Assert
            Assert.Equal("Doe, Jane", student.FullName);
            Assert.IsAssignableFrom<Person>(student);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void Instructor_SetHireDate_ReturnsCorrectDate()
        {
            // Arrange
            var hireDate = new DateTime(2020, 1, 15);
            var instructor = new Instructor { HireDate = hireDate };

            // Assert
            Assert.Equal(hireDate, instructor.HireDate);
        }

        [Fact]
        public void Instructor_InheritsFromPerson_HasFullName()
        {
            // Arrange
            var instructor = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "Alice",
                HireDate = DateTime.Now
            };

            // Assert
            Assert.Equal("Smith, Alice", instructor.FullName);
            Assert.IsAssignableFrom<Person>(instructor);
        }

        [Fact]
        public void Instructor_DefaultCourseAssignments_IsNull()
        {
            // Arrange & Act
            var instructor = new Instructor();

            // Assert
            Assert.Null(instructor.CourseAssignments);
        }

        [Fact]
        public void Instructor_DefaultOfficeAssignment_IsNull()
        {
            // Arrange & Act
            var instructor = new Instructor();

            // Assert
            Assert.Null(instructor.OfficeAssignment);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_SetProperties_ReturnsCorrectValues()
        {
            // Arrange & Act
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };

            // Assert
            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
        }

        [Fact]
        public void Course_TeachingMaterialImagePath_DefaultIsNull()
        {
            // Arrange & Act
            var course = new Course();

            // Assert
            Assert.Null(course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_SetTeachingMaterialImagePath_ReturnsCorrectValue()
        {
            // Arrange
            var path = "/Uploads/TeachingMaterials/course_1050_abc.jpg";
            var course = new Course { TeachingMaterialImagePath = path };

            // Assert
            Assert.Equal(path, course.TeachingMaterialImagePath);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_SetProperties_ReturnsCorrectValues()
        {
            // Arrange & Act
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 5
            };

            // Assert
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            // Arrange & Act
            var dept = new Department { InstructorID = null };

            // Assert
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Department_RowVersion_DefaultIsNull()
        {
            // Arrange & Act
            var dept = new Department();

            // Assert
            Assert.Null(dept.RowVersion);
        }
    }

    public class EnrollmentTests
