        public void SchoolContext_HasEnrollmentsDbSet()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Assert
            Assert.NotNull(context.Enrollments);
        }

        [Fact]
        public void SchoolContext_HasNotificationsDbSet()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Assert
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using (var context = TestDbContextHelper.CreateContext(dbName))
            {
                var student = new Student
                {
                    FirstMidName = "Test",
                    LastName = "Student",
                    EnrollmentDate = new DateTime(2024, 1, 1)
                };
                context.Students.Add(student);
                context.SaveChanges();
            }

            // Act
            using (var context = TestDbContextHelper.CreateContext(dbName))
            {
                var student = context.Students.First();

                // Assert
                Assert.Equal("Test", student.FirstMidName);
                Assert.Equal("Student", student.LastName);
                Assert.Equal(new DateTime(2024, 1, 1), student.EnrollmentDate);
            }
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveCourse()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 100000,
                StartDate = DateTime.Now
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 9999,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            // Act
            var retrieved = context.Courses.Find(9999);

            // Assert
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Now
            };
            context.Instructors.Add(instructor);

            var dept = new Department
            {
                Name = "Test",
                Budget = 50000,
                StartDate = DateTime.Now
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 8888,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            // Act
            var retrieved = context.CourseAssignments.Find(course.CourseID, instructor.ID);

            // Assert
            Assert.NotNull(retrieved);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
        }
    }

    public class DbInitializerTests
