using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using Xunit;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Contact_ReturnsViewResult()
        {
            // Act
            var result = _controller.Contact();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsViewResult()
        {
            // Act
            var result = _controller.Error();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewResult_WithMessage()
        {
            // Act
            var result = _controller.Unauthorized();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
        }

        [Fact]
        public void About_WithNoStudents_ReturnsEmptyList()
        {
            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Models.SchoolViewModels.EnrollmentDateGroup>>(viewResult.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void About_WithStudents_ReturnsGroupedData()
        {
            // Arrange
            var date1 = new DateTime(2024, 9, 1);
            var date2 = new DateTime(2023, 9, 1);
            _context.Students.AddRange(
                new Student { FirstMidName = "A", LastName = "One", EnrollmentDate = date1 },
                new Student { FirstMidName = "B", LastName = "Two", EnrollmentDate = date1 },
                new Student { FirstMidName = "C", LastName = "Three", EnrollmentDate = date2 }
            );
            _context.SaveChanges();

            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Models.SchoolViewModels.EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(2, model.Count);
            Assert.Contains(model, g => g.EnrollmentDate == date1 && g.StudentCount == 2);
            Assert.Contains(model, g => g.EnrollmentDate == date2 && g.StudentCount == 1);
        }
    }
}

