        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department AddTestDepartment(string name = "Test Dept", decimal budget = 100000, int? instructorId = null)
        {
            var dept = new Department
            {
                Name = name,
                Budget = budget,
                StartDate = new DateTime(2024, 1, 1),
                InstructorID = instructorId
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Instructor AddTestInstructor(string firstName = "Jane", string lastName = "Prof")
        {
            var instructor = new Instructor
            {
                FirstMidName = firstName,
                LastName = lastName,
