using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using Xunit;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor AddTestInstructor(string firstName = "Jane", string lastName = "Doe", DateTime? hireDate = null)
        {
            var instructor = new Instructor
            {
                FirstMidName = firstName,
                LastName = lastName,
                HireDate = hireDate ?? new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        private Department AddTestDepartment(string name = "Test Dept")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course AddTestCourse(int courseId, string title, int departmentId)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // ===== Index =====

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructors()
        {
            // Arrange
            AddTestInstructor("Alice", "Smith");
            AddTestInstructor("Bob", "Jones");

            // Act
            var result = _controller.Index(null, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_SetsCoursesOnModel()
        {
            // Arrange
            var dept = AddTestDepartment();
            var instructor = AddTestInstructor();
            var course = AddTestCourse(1001, "Test Course", dept.DepartmentID);
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });
            _context.SaveChanges();

            // Act
            var result = _controller.Index(instructor.ID, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        // ===== Details =====

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructor = AddTestInstructor("Alice", "Smith");

            // Act
            var result = _controller.Details(instructor.ID);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.Equal("Alice", model.FirstMidName);
            Assert.Equal("Smith", model.LastName);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(9999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        // ===== Create (GET) =====

        [Fact]
        public void Create_Get_ReturnsViewWithNewInstructor()
        {
            // Act
            var result = _controller.Create();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
        }

        // ===== Create (POST) =====

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2024, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null);

            // Assert
            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Equal(1, _context.Instructors.Count());
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            // Arrange
            var dept = AddTestDepartment();
            var course = AddTestCourse(2001, "Test Course", dept.DepartmentID);
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2024, 1, 1)
            };

            // Act
            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() });

            // Assert
            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            var saved = _context.Instructors.Include(i => i.CourseAssignments).First();
            Assert.Single(saved.CourseAssignments);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null);

            // Assert
            Assert.IsType<ViewResult>(result);
        }

