using System;
using System.Collections.Generic;
using Xunit;
using Microsoft.AspNetCore.Mvc;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new NotificationsController(_context);
            // Drain the static notification queue for test isolation
            while (_controller.GetNotifications() is JsonResult jr1)
            {
                var val = jr1.Value;
                var countProp = val?.GetType().GetProperty("count");
                if (countProp != null)
                {
                    var count = (int)countProp.GetValue(val);
                    if (count == 0) break;
                }
                else break;
            }
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsSuccessWithEmptyList()
        {
            // Drain any leftovers first
            JsonResult drainResult;
            do
            {
                drainResult = _controller.GetNotifications();
                var val = drainResult.Value;
                var countProp = val?.GetType().GetProperty("count");
                if (countProp == null || (int)countProp.GetValue(val) == 0)
                    break;
            } while (true);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
            var countProperty = value.GetType().GetProperty("count");
            Assert.Equal(0, (int)countProperty.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Arrange - use the controller's notificationService via SendEntityNotification (inherited from BaseController)
            // We access it indirectly by using another controller to send a notification
            var studentController = new StudentsController(_context);
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2024, 9, 1)
            };
            studentController.Create(student);
            studentController.Dispose();

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void MarkAsRead_ValidId_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void MarkAsRead_InvalidId_StillReturnsSuccess()
        {
            // The in-memory implementation is a no-op
            // Act
            var result = _controller.MarkAsRead(-1);

            // Assert
            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }
    }
}

